import math


def _sigmoid(z):
    if z >= 0:
        return 1 / (1 + math.exp(-z))
    e = math.exp(z)
    return e / (1 + e)


ACTIVATIONS = {
    "relu": lambda z: max(0.0, z),
    "tanh": math.tanh,
    "sigmoid": _sigmoid,
    "linear": lambda z: z,
}


def forward(x, layers):
    for weights, biases, activation in layers:
        if activation not in ACTIVATIONS:
            raise ValueError(f"unknown activation {activation!r}")
        f = ACTIVATIONS[activation]
        x = [f(sum(w * v for w, v in zip(row, x)) + bias) for row, bias in zip(weights, biases)]
    return x
